// Independent DR-0129 phase 0 wire-vector reconstruction for the FastVote
// payload (0xD006), FastVote (0xD007), and FastCertificate (0xD008)
// canonical frames, plus the DR-0132 phase 2 slice 2 epoch-transition
// vote payload (0xD009), vote (0xD00A), and certificate (0xD00B) canonical
// frames. No Rust encoder is invoked; this reimplements the shared
// canonical-frame layout (crates/canonical-encoding) and the
// self-describing Digest32 frame (0x0103) from scratch and checks the
// result against the exact hex pinned by the co-located Rust vectors in
// crates/consensus/src/fast_vote.rs and
// crates/consensus/src/epoch_transition.rs.
// Run: node scripts/fast-vote-vectors.mjs
import assert from 'node:assert/strict';

const u16 = (n) => { const b = Buffer.alloc(2); b.writeUInt16LE(n); return b; };
const u32 = (n) => { const b = Buffer.alloc(4); b.writeUInt32LE(n); return b; };
const u64 = (n) => { const b = Buffer.alloc(8); b.writeBigUInt64LE(BigInt(n)); return b; };
const frame = (id, version, fields) => Buffer.concat([
  Buffer.from('SNRE'), u16(id), u16(version), u16(fields.length),
  ...fields.flatMap(([key, value]) => [u16(key), u32(value.length), value]),
]);

const ENCODING_VERSION = 1;
const FAST_VOTE_PAYLOAD_TYPE_ID = 0xd006;
const FAST_VOTE_TYPE_ID = 0xd007;
const FAST_CERTIFICATE_TYPE_ID = 0xd008;
const DIGEST32_TYPE_ID = 0x0103;
const SHA2_256_ALGORITHM_ID = 1;
const ED25519_SCHEME_ID = 1;

const digest32 = (byte) => frame(DIGEST32_TYPE_ID, 1, [
  [1, u16(SHA2_256_ALGORITHM_ID)],
  [2, Buffer.alloc(32, byte)],
]);

const CHAIN_ID = 'dr0129-vectors';
const PROTOCOL_VERSION = 3;
const EPOCH = 9;
const TX_HASH = digest32(0xaa);
const EFFECTS_HASH = digest32(0xbb);
const LOCKED_OBJECTS_DIGEST = digest32(0xcc);

const fastVotePayload = (validatorByte) => frame(FAST_VOTE_PAYLOAD_TYPE_ID, ENCODING_VERSION, [
  [1, Buffer.from(CHAIN_ID)],
  [2, u32(PROTOCOL_VERSION)],
  [3, u64(EPOCH)],
  [4, TX_HASH],
  [5, EFFECTS_HASH],
  [6, Buffer.alloc(32, validatorByte)],
  [7, u16(ED25519_SCHEME_ID)],
  [8, LOCKED_OBJECTS_DIGEST],
]);

const fastVote = (validatorByte, signatureByte) => frame(FAST_VOTE_TYPE_ID, ENCODING_VERSION, [
  [1, fastVotePayload(validatorByte)],
  [2, Buffer.alloc(64, signatureByte)],
]);

const voteA = fastVote(0x01, 0x5a);
const voteB = fastVote(0x02, 0x7c);
const fastCertificate = frame(FAST_CERTIFICATE_TYPE_ID, ENCODING_VERSION, [
  [1, Buffer.from(CHAIN_ID)],
  [2, u32(PROTOCOL_VERSION)],
  [3, u64(EPOCH)],
  [4, TX_HASH],
  [5, EFFECTS_HASH],
  [6, LOCKED_OBJECTS_DIGEST],
  [7, u32(2)],
  [8, voteA],
  [9, voteB],
]);

const vectors = {
  fastVotePayload0xd006: fastVotePayload(0x01),
  fastVote0xd007: voteA,
  fastCertificate0xd008: fastCertificate,
};

const expected = {
  fastVotePayload0xd006: '',
  fastVote0xd007: '',
  fastCertificate0xd008: '',
};

for (const [name, bytes] of Object.entries(vectors)) {
  const hex = bytes.toString('hex');
  assert.equal(hex, expected[name], `${name} hex mismatch`);
  console.log(JSON.stringify({ name, length: bytes.length, hex }));
}

// DR-0132 epoch-transition vote/certificate vectors (0xD009-0xD00B).
const ET_PAYLOAD_TYPE_ID = 0xd009;
const ET_VOTE_TYPE_ID = 0xd00a;
const ET_CERTIFICATE_TYPE_ID = 0xd00b;

const ET_CHAIN_ID = 'dr0132-vectors';
const ET_PROTOCOL_VERSION = 3;
const ET_EPOCH = 9;
const ET_NEXT_EPOCH = 10;
const ET_CURRENT_DIGEST = digest32(0xaa);
const ET_NEXT_DIGEST = digest32(0xbb);
const ET_ACTIVATION_DIGEST = digest32(0xcc);

const etVotePayload = (validatorByte) => frame(ET_PAYLOAD_TYPE_ID, ENCODING_VERSION, [
  [1, Buffer.from(ET_CHAIN_ID)],
  [2, u32(ET_PROTOCOL_VERSION)],
  [3, u64(ET_EPOCH)],
  [4, u64(ET_NEXT_EPOCH)],
  [5, ET_CURRENT_DIGEST],
  [6, ET_NEXT_DIGEST],
  [7, ET_ACTIVATION_DIGEST],
  [8, Buffer.alloc(32, validatorByte)],
  [9, u16(ED25519_SCHEME_ID)],
]);

const etVote = (validatorByte, signatureByte) => frame(ET_VOTE_TYPE_ID, ENCODING_VERSION, [
  [1, etVotePayload(validatorByte)],
  [2, Buffer.alloc(64, signatureByte)],
]);

const etVoteA = etVote(0x01, 0x5a);
const etVoteB = etVote(0x02, 0x7c);
const etCertificate = frame(ET_CERTIFICATE_TYPE_ID, ENCODING_VERSION, [
  [1, Buffer.from(ET_CHAIN_ID)],
  [2, u32(ET_PROTOCOL_VERSION)],
  [3, u64(ET_EPOCH)],
  [4, u64(ET_NEXT_EPOCH)],
  [5, ET_CURRENT_DIGEST],
  [6, ET_NEXT_DIGEST],
  [7, ET_ACTIVATION_DIGEST],
  [8, u32(2)],
  [9, etVoteA],
  [10, etVoteB],
]);

const etVectors = {
  epochTransitionVotePayload0xd009: etVotePayload(0x01),
  epochTransitionVote0xd00a: etVoteA,
  epochTransitionCertificate0xd00b: etCertificate,
};

const etExpected = {
  epochTransitionVotePayload0xd009: '',
  epochTransitionVote0xd00a: '',
  epochTransitionCertificate0xd00b: '',
};

for (const [name, bytes] of Object.entries(etVectors)) {
  const hex = bytes.toString('hex');
  assert.equal(hex, etExpected[name], `${name} hex mismatch`);
  console.log(JSON.stringify({ name, length: bytes.length, hex }));
}

// DR-0133 equivocation evidence vectors (0xD00C-0xD00F).
const LOCKED_OBJECT_SET_PREIMAGE_TYPE_ID = 0xd00c;
const FAST_VOTE_EQUIVOCATION_EVIDENCE_TYPE_ID = 0xd00d;
const FAST_VOTE_OBJECT_CONFLICT_EVIDENCE_TYPE_ID = 0xd00e;
const EPOCH_TRANSITION_EQUIVOCATION_EVIDENCE_TYPE_ID = 0xd00f;

const OBJECT_ID_TYPE_ID = 0x4001;
const OBJECT_REF_TYPE_ID = 0x4004;
const objectId = (byte) => frame(OBJECT_ID_TYPE_ID, ENCODING_VERSION, [[1, Buffer.alloc(32, byte)]]);
const objectRef = (idByte, version, digestByte) => frame(OBJECT_REF_TYPE_ID, ENCODING_VERSION, [
  [1, objectId(idByte)],
  [2, u64(version)],
  [3, digest32(digestByte)],
]);

const EQ_CHAIN_ID = 'dr0133-vectors';
const EQ_PROTOCOL_VERSION = 3;
const EQ_EPOCH = 9;

const lockedObjectSetPreimage = (entries) => frame(LOCKED_OBJECT_SET_PREIMAGE_TYPE_ID, ENCODING_VERSION, [
  [1, Buffer.from(EQ_CHAIN_ID)],
  [2, u32(EQ_PROTOCOL_VERSION)],
  [3, u64(EQ_EPOCH)],
  [4, u32(entries.length)],
  ...entries.map((entry, index) => [index + 5, entry]),
]);

const preimage0xD00C = lockedObjectSetPreimage([
  objectRef(0x10, 1, 0x20),
  objectRef(0x30, 2, 0x40),
]);

const eqFastVotePayload = (txHash, effectsHash, validatorByte, lockedObjectsDigest) => frame(FAST_VOTE_PAYLOAD_TYPE_ID, ENCODING_VERSION, [
  [1, Buffer.from(EQ_CHAIN_ID)],
  [2, u32(EQ_PROTOCOL_VERSION)],
  [3, u64(EQ_EPOCH)],
  [4, txHash],
  [5, effectsHash],
  [6, Buffer.alloc(32, validatorByte)],
  [7, u16(ED25519_SCHEME_ID)],
  [8, lockedObjectsDigest],
]);

const eqFastVote = (txHash, effectsHash, validatorByte, lockedObjectsDigest, signatureByte) => frame(FAST_VOTE_TYPE_ID, ENCODING_VERSION, [
  [1, eqFastVotePayload(txHash, effectsHash, validatorByte, lockedObjectsDigest)],
  [2, Buffer.alloc(64, signatureByte)],
]);

const eqVoteA = eqFastVote(digest32(0xaa), digest32(0xbb), 0x01, digest32(0xcc), 0x5a);
const eqVoteB = eqFastVote(digest32(0xaa), digest32(0xdd), 0x01, digest32(0xcc), 0x7c);
const eqVoteC = eqFastVote(digest32(0xee), digest32(0xbb), 0x01, digest32(0xcc), 0x9b);

const fastVoteEquivocationEvidence = frame(FAST_VOTE_EQUIVOCATION_EVIDENCE_TYPE_ID, ENCODING_VERSION, [
  [1, Buffer.from(EQ_CHAIN_ID)],
  [2, u32(EQ_PROTOCOL_VERSION)],
  [3, u64(EQ_EPOCH)],
  [4, digest32(0xaa)],
  [5, Buffer.alloc(32, 0x01)],
  [6, eqVoteA],
  [7, eqVoteB],
]);

const singleEntryPreimage = lockedObjectSetPreimage([objectRef(0x10, 1, 0x20)]);
const fastVoteObjectConflictEvidence = frame(FAST_VOTE_OBJECT_CONFLICT_EVIDENCE_TYPE_ID, ENCODING_VERSION, [
  [1, Buffer.from(EQ_CHAIN_ID)],
  [2, u32(EQ_PROTOCOL_VERSION)],
  [3, u64(EQ_EPOCH)],
  [4, Buffer.alloc(32, 0x01)],
  [5, Buffer.alloc(32, 0x10)],
  [6, u64(1)],
  [7, eqVoteA],
  [8, singleEntryPreimage],
  [9, eqVoteC],
  [10, singleEntryPreimage],
]);

const eqEtVotePayload = (activationDigest, validatorByte) => frame(ET_PAYLOAD_TYPE_ID, ENCODING_VERSION, [
  [1, Buffer.from(EQ_CHAIN_ID)],
  [2, u32(EQ_PROTOCOL_VERSION)],
  [3, u64(EQ_EPOCH)],
  [4, u64(10)],
  [5, digest32(0xaa)],
  [6, digest32(0xbb)],
  [7, activationDigest],
  [8, Buffer.alloc(32, validatorByte)],
  [9, u16(ED25519_SCHEME_ID)],
]);

const eqEtVote = (activationDigest, validatorByte, signatureByte) => frame(ET_VOTE_TYPE_ID, ENCODING_VERSION, [
  [1, eqEtVotePayload(activationDigest, validatorByte)],
  [2, Buffer.alloc(64, signatureByte)],
]);

const eqTransitionVoteA = eqEtVote(digest32(0xcc), 0x01, 0x5a);
const eqTransitionVoteB = eqEtVote(digest32(0xdd), 0x01, 0x7c);

const epochTransitionEquivocationEvidence = frame(EPOCH_TRANSITION_EQUIVOCATION_EVIDENCE_TYPE_ID, ENCODING_VERSION, [
  [1, Buffer.from(EQ_CHAIN_ID)],
  [2, u32(EQ_PROTOCOL_VERSION)],
  [3, u64(EQ_EPOCH)],
  [4, Buffer.alloc(32, 0x01)],
  [5, eqTransitionVoteA],
  [6, eqTransitionVoteB],
]);

const eqVectors = {
  lockedObjectSetPreimage0xd00c: preimage0xD00C,
  fastVoteEquivocationEvidence0xd00d: fastVoteEquivocationEvidence,
  fastVoteObjectConflictEvidence0xd00e: fastVoteObjectConflictEvidence,
  epochTransitionEquivocationEvidence0xd00f: epochTransitionEquivocationEvidence,
};

const eqExpected = {
  lockedObjectSetPreimage0xd00c: '',
  fastVoteEquivocationEvidence0xd00d: '',
  fastVoteObjectConflictEvidence0xd00e: '',
  epochTransitionEquivocationEvidence0xd00f: '',
};

for (const [name, bytes] of Object.entries(eqVectors)) {
  const hex = bytes.toString('hex');
  assert.equal(hex, eqExpected[name], `${name} hex mismatch`);
  console.log(JSON.stringify({ name, length: bytes.length, hex }));
}
